import java.util.*; import java.util.stream.*; class Solution {record Sale(String team,int amount){}static Map<String,Integer> totals(List<Sale> sales){return sales.stream().collect(Collectors.groupingBy(Sale::team,TreeMap::new,Collectors.summingInt(Sale::amount)));}static Map<Boolean,List<Sale>> partition(List<Sale> sales){return sales.stream().collect(Collectors.partitioningBy(sale->sale.amount()>=100));}}
